import com.jpexs.decompiler.flash.*;import com.jpexs.decompiler.flash.tags.*;import java.io.*;
class VerifyBanner{public static void main(String[]args)throws Exception{SWF a=new SWF(new FileInputStream(args[0]),false),b=new SWF(new FileInputStream(args[1]),false);int changed=0;for(int j=0;j<a.getTags().size();j++)if(a.getTags().get(j) instanceof DoABC2Tag){var x=((DoABC2Tag)a.getTags().get(j)).getABC();var y=((DoABC2Tag)b.getTags().get(j)).getABC();for(var body:x.bodies){byte[] old=body.getCodeBytes(),now=y.findBody(body.method_info).getCodeBytes();if(old.length!=now.length)throw new Exception("Length changed");for(int i=0;i<old.length;i++)if(old[i]!=now[i]){if(old[i]!=0x26||now[i]!=0x27)throw new Exception("Unexpected change");changed++;}}}if(changed!=1)throw new Exception("Unexpected difference count");System.out.println("PASS: exactly one byte changed, pushtrue to pushfalse; all other method bytes identical");}}
